26	/**
27	 * @title Legion Sealed Bid Auction
28	 * @author Legion
29	 * @notice Executes sealed bid auctions of ERC20 tokens after Token Generation Event (TGE).
30	 * @dev Inherits from LegionAbstractSale and implements ILegionSealedBidAuctionSale with ECIES encryption features for
31	 * bid privacy.
32	 */
33	contract LegionSealedBidAuctionSale is LegionAbstractSale, ILegionSealedBidAuctionSale {
34	    /// @dev Struct containing the sealed bid auction sale configuration
35	    SealedBidAuctionSaleConfiguration private s_sealedBidAuctionSaleConfig;
36	
37	    /// @notice Restricts interaction to when the sale cancelation is locked.
38	    /// @dev Reverts if canceling is not locked.
39	    modifier whenCancelLocked() {
40	        // Verify that canceling is locked
41	        _verifyCancelLocked();
42	        _;
43	    }
44	
45	    /// @notice Restricts interaction to when the sale cancelation is not locked.
46	    /// @dev Reverts if canceling is locked.
47	    modifier whenCancelNotLocked() {
48	        // Verify that canceling is not locked
49	        _verifyCancelNotLocked();
50	        _;
51	    }
52	
53	    /// @inheritdoc ILegionSealedBidAuctionSale
54	    function initialize(
55	        LegionSaleInitializationParams calldata saleInitParams,
56	        SealedBidAuctionSaleInitializationParams calldata sealedBidAuctionSaleInitParams
57	    )
58	        external
59	        initializer
60	    {
61	        // Verify if the sale initialization parameters are valid
62	        _verifyValidParams(sealedBidAuctionSaleInitParams);
63	
64	        // Initialize and set the sale common parameters
65	        _setLegionSaleConfig(saleInitParams);
66	
67	        // Set the sealed bid auction sale specific configuration
68	        (s_sealedBidAuctionSaleConfig.publicKey) = sealedBidAuctionSaleInitParams.publicKey;
69	
70	        // Calculate and set startTime, endTime and refundEndTime
71	        s_saleConfig.startTime = uint64(block.timestamp);
72	        s_saleConfig.endTime = s_saleConfig.startTime + saleInitParams.salePeriodSeconds;
73	        s_saleConfig.refundEndTime = s_saleConfig.endTime + saleInitParams.refundPeriodSeconds;
74	    }
75	
76	    /// @inheritdoc ILegionSealedBidAuctionSale
77	    function invest(
78	        uint256 amount,
79	        bytes calldata sealedBid,
80	        bytes calldata signature
81	    )
82	        external
83	        whenNotPaused
84	        whenSaleNotEnded
85	        whenSaleNotCanceled
86	    {
87	        // Check if the investor has already invested
88	        // If not, create a new investor position
89	        uint256 positionId = _getInvestorPositionId(msg.sender) == 0
90	            ? _createInvestorPosition(msg.sender)
91	            : s_investorPositionIds[msg.sender];
92	
93	        // Verify that the investor is allowed to invest capital
94	        _verifyInvestSignature(signature);
95	
96	        // Decode the sealed bid data
97	        (uint256 encryptedAmountOut, Point memory sealedBidPublicKey) = abi.decode(sealedBid, (uint256, Point));
98	
99	        // Verify that the provided public key is valid
100	        _verifyValidPublicKey(sealedBidPublicKey);
101	
102	        // Verify that the amount invested is more than the minimum required
103	        _verifyMinimumInvestAmount(amount);
104	
105	        // Verify that the investor has not refunded
106	        _verifyHasNotRefunded(positionId);
107	
108	        // Verify that the investor has not claimed excess capital
109	        _verifyHasNotClaimedExcess(positionId);
110	
111	        // Increment total capital invested from all investors
112	        s_saleStatus.totalCapitalInvested += amount;
113	
114	        // Increment total invested capital for the investor
115	        s_investorPositions[positionId].investedCapital += amount;
116	
117	        // Emit CapitalInvested event
118	        emit CapitalInvested(amount, encryptedAmountOut, msg.sender, positionId);
119	
120	        // Transfer the invested capital to the contract
121	        SafeTransferLib.safeTransferFrom(s_addressConfig.bidToken, msg.sender, address(this), amount);
122	    }
123	
124	    /// @inheritdoc ILegionSealedBidAuctionSale
125	    function initializePublishSaleResults()
126	        external
127	        onlyLegion
128	        whenNotPaused
129	        whenSaleNotCanceled
130	        whenCancelNotLocked
131	        whenRefundPeriodIsOver
132	    {
133	        // Verify that sale results are not already published
134	        _verifyCanPublishSaleResults();
135	
136	        // Flag that the sale is locked from canceling
137	        s_sealedBidAuctionSaleConfig.cancelLocked = true;
138	
139	        // Emit PublishSaleResultsInitialized event
140	        emit PublishSaleResultsInitialized();
141	    }
142	
143	    /// @inheritdoc ILegionSealedBidAuctionSale
144	    function publishSaleResults(
145	        bytes32 claimMerkleRoot,
146	        bytes32 acceptedMerkleRoot,
147	        uint256 tokensAllocated,
148	        uint256 capitalRaised,
149	        uint256 sealedBidPrivateKey,
150	        uint256 fixedSalt
151	    )
152	        external
153	        onlyLegion
154	        whenNotPaused
155	        whenSaleNotCanceled
156	        whenRefundPeriodIsOver
157	        whenCancelLocked
158	    {
159	        // Verify if the provided private key is valid
160	        _verifyValidPrivateKey(sealedBidPrivateKey);
161	
162	        // Verify that sale results are not already published
163	        _verifyCanPublishSaleResults();
164	
165	        // Set the merkle root for claiming tokens
166	        s_saleStatus.claimTokensMerkleRoot = claimMerkleRoot;
167	
168	        // Set the merkle root for accepted capital
169	        s_saleStatus.acceptedCapitalMerkleRoot = acceptedMerkleRoot;
170	
171	        // Set the total tokens to be allocated by the Project team
172	        s_saleStatus.totalTokensAllocated = tokensAllocated;
173	
174	        // Set the total capital raised to be withdrawn by the project
175	        s_saleStatus.totalCapitalRaised = capitalRaised;
176	
177	        // Set the private key used to decrypt sealed bids
178	        s_sealedBidAuctionSaleConfig.privateKey = sealedBidPrivateKey;
179	
180	        // Set the fixed salt used for sealing bids
181	        s_sealedBidAuctionSaleConfig.fixedSalt = fixedSalt;
182	
183	        // Emit SaleResultsPublished event
184	        emit SaleResultsPublished(
185	            claimMerkleRoot, acceptedMerkleRoot, tokensAllocated, capitalRaised, sealedBidPrivateKey, fixedSalt
186	        );
187	    }
188	
189	    /// @inheritdoc ILegionSealedBidAuctionSale
190	    function sealedBidAuctionSaleConfiguration() external view returns (SealedBidAuctionSaleConfiguration memory) {
191	        return s_sealedBidAuctionSaleConfig;
192	    }
193	
194	    /// @inheritdoc ILegionAbstractSale
195	    function cancel()
196	        public
197	        override(ILegionAbstractSale, LegionAbstractSale)
198	        onlyProject
199	        whenNotPaused
200	        whenCancelNotLocked
201	    {
202	        // Call parent method
203	        super.cancel();
204	    }
205	
206	    /// @inheritdoc ILegionSealedBidAuctionSale
207	    function decryptSealedBid(uint256 encryptedAmountOut, address investor) external view returns (uint256) {
208	        // Verify that the private key has been published by Legion
209	        _verifyPrivateKeyIsPublished();
210	
211	        // Cache the sealed bid auction sale configuration
212	        SealedBidAuctionSaleConfiguration memory sealedBidAuctionSaleConfig = s_sealedBidAuctionSaleConfig;
213	
214	        // Decrypt the sealed bid
215	        return ECIES.decrypt(
216	            encryptedAmountOut,
217	            sealedBidAuctionSaleConfig.publicKey,
218	            sealedBidAuctionSaleConfig.privateKey,
219	            uint256(keccak256(abi.encodePacked(investor, sealedBidAuctionSaleConfig.fixedSalt)))
220	        );
221	    }
222	
223	    /// @dev Verifies the validity of sealed bid auction initialization parameters.
224	    /// @param _sealedBidAuctionSaleInitParams The auction-specific parameters to validate.
225	    function _verifyValidParams(SealedBidAuctionSaleInitializationParams calldata _sealedBidAuctionSaleInitParams)
226	        private
227	        pure
228	    {
229	        // Check if the public key used for encryption is valid
230	        if (!ECIES.isValid(_sealedBidAuctionSaleInitParams.publicKey)) {
231	            revert Errors.LegionSale__InvalidBidPublicKey();
232	        }
233	    }
234	
235	    /// @dev Verifies the validity of the public key used in a sealed bid.
236	    /// @param _publicKey The public key provided in the sealed bid.
237	    function _verifyValidPublicKey(Point memory _publicKey) private view {
238	        // Verify that the _publicKey is a valid point for the encryption library
239	        if (!ECIES.isValid(_publicKey)) revert Errors.LegionSale__InvalidBidPublicKey();
240	
241	        // Cache the sealed bid auction sale configuration
242	        SealedBidAuctionSaleConfiguration memory sealedBidAuctionSaleConfig = s_sealedBidAuctionSaleConfig;
243	
244	        // Verify that the _publicKey is the one used for the entire auction
245	        if (
246	            keccak256(abi.encodePacked(_publicKey.x, _publicKey.y))
247	                != keccak256(
248	                    abi.encodePacked(sealedBidAuctionSaleConfig.publicKey.x, sealedBidAuctionSaleConfig.publicKey.y)
249	                )
250	        ) revert Errors.LegionSale__InvalidBidPublicKey();
251	    }
252	
253	    /// @dev Verifies the validity of the private key for decrypting bids.
254	    /// @param _privateKey The private key provided for decryption.
255	    function _verifyValidPrivateKey(uint256 _privateKey) private view {
256	        // Cache the sealed bid auction sale configuration
257	        SealedBidAuctionSaleConfiguration memory sealedBidAuctionSaleConfig = s_sealedBidAuctionSaleConfig;
258	
259	        // Verify that the private key has not already been published
260	        if (sealedBidAuctionSaleConfig.privateKey != 0) {
261	            revert Errors.LegionSale__PrivateKeyAlreadyPublished();
262	        }
263	
264	        // Verify that the private key is valid for the public key
265	        Point memory calcPubKey = ECIES.calcPubKey(Point(1, 2), _privateKey);
266	        if (
267	            calcPubKey.x != sealedBidAuctionSaleConfig.publicKey.x
268	                || calcPubKey.y != sealedBidAuctionSaleConfig.publicKey.y
269	        ) revert Errors.LegionSale__InvalidBidPrivateKey();
270	    }
271	
272	    /// @dev Verifies that the private key has been published.
273	    function _verifyPrivateKeyIsPublished() private view {
274	        if (s_sealedBidAuctionSaleConfig.privateKey == 0) {
275	            revert Errors.LegionSale__PrivateKeyNotPublished();
276	        }
277	    }
278	
279	    /// @dev Verifies that cancellation is not locked.
280	    function _verifyCancelNotLocked() private view {
281	        if (s_sealedBidAuctionSaleConfig.cancelLocked) {
282	            revert Errors.LegionSale__CancelLocked();
283	        }
284	    }
285	
286	    /// @dev Verifies that cancellation is locked.
287	    function _verifyCancelLocked() private view {
288	        if (!s_sealedBidAuctionSaleConfig.cancelLocked) {
289	            revert Errors.LegionSale__CancelNotLocked();
290	        }
291	    }
292	}
